  "ws-client-message": {
    "$defs": {
      "channel": {
        "description": "A frame type of ws-server-message; the two enums are asserted equal in test/ws-api.test.ts.",
        "enum": [
          "hello",
          "snapshot",
          "heartbeat",
          "telemetry.samples",
          "telemetry.series",
          "status.sim",
          "status.gateway",
          "status.backend",
          "event.suspect",
          "decision",
          "ticket",
          "alert.system",
          "alarm.native",
          "overlay.catalog",
          "overlay.injection",
          "overlay.injection_active",
          "overlay.marker",
          "cost.update"
        ],
        "title": "Channel",
        "type": "string"
      },
      "channel_list": {
        "description": "The frame types the socket wants from now on. An empty list mutes every channel.",
        "items": {
          "$ref": "#/$defs/channel"
        },
        "title": "Channel list",
        "type": "array",
        "uniqueItems": true
      }
    },
    "$id": "urn:fdp:schema:ws-client-message:v1",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": false,
    "description": "The only two frames a browser may send on GET /ws. `subscribe` narrows the frame types the socket receives; `ping` keeps the socket alive and is answered by nothing. Commands never travel over the socket: they are REST posts validated with api-sim-command. The default subscription is every ws-server-message type except telemetry.samples, which a client has to ask for by name.",
    "oneOf": [
      {
        "description": "Replace the subscription of this socket with the named channels.",
        "properties": {
          "channels": {
            "$ref": "#/$defs/channel_list"
          },
          "type": {
            "const": "subscribe"
          }
        },
        "required": [
          "type",
          "channels"
        ]
      },
      {
        "description": "Keep the socket alive. The frame carries nothing else.",
        "properties": {
          "channels": false,
          "type": {
            "const": "ping"
          }
        },
        "required": [
          "type"
        ]
      }
    ],
    "properties": {
      "channels": {
        "$ref": "#/$defs/channel_list"
      },
      "type": {
        "description": "Which of the two client frames this is.",
        "enum": [
          "subscribe",
          "ping"
        ],
        "type": "string"
      }
    },
    "required": [
      "type"
    ],
    "title": "Ws client message",
    "type": "object"
  },
